    def draft_trim(x0, x1):
        n = cq.Vector(0, draft_ny, draft_nz).normalized()
        pl = cq.Plane(origin=n * draft_d, xDir=cq.Vector(1, 0, 0), normal=n)
        half_space = cq.Workplane(pl).rect(400, 400).extrude(20).val()
        window = cq.Solid.makeBox(x1 - x0, 10, draft_z1 - draft_z0, cq.Vector(x0, draft_y0, draft_z0))
        boss = cq.Solid.makeCylinder(boss_r, 12, cq.Vector(axis_x, draft_y0 - 3, axis_z), cq.Vector(0, 1, 0))
